# -*- coding: utf-8 -*-
r"""qc_fix_workspace_refs.py — 清理 .obsidian/workspace.json 里指向已不存在路径的死引用。

背景
----
`workspace.json` 记录 Obsidian 的标签页/最近文件状态。当库结构变动（改名、目录精简、
PDF 改名）后，其中的路径会变成**指向不存在文件**的死引用。
Obsidian 打开时**不报错**，只是该标签页显示为空——正是 CLAUDE.md 记的
「书签/路径指向不存在时 Obsidian 不报错，只是静默消失」的同一形态。

做法
----
只删「确实不存在」的条目，**保留其余全部状态**；默认干跑。
同时清理 `lastOpenFiles` 里已不存在的路径。

⚠️ 仅在 Obsidian **未运行**时执行——否则 Obsidian 退出时会用内存状态覆盖回去。
本脚本会检查并拒绝在 Obsidian 运行时写盘。

用法:
    python tools/qc_fix_workspace_refs.py              # 干跑
    python tools/qc_fix_workspace_refs.py --apply      # 写盘（先备份到库根 .qc/）
    python tools/qc_fix_workspace_refs.py --selftest   # 校验器自检
"""
import os
import sys
import json
import glob
import shutil
import datetime
import argparse
import subprocess


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import qc_work_dir  # noqa: E402
from kb_lib import console_encoding
console_encoding()

WS = ".obsidian/workspace.json"


def obsidian_running():
    """Obsidian 是否在运行（Windows）。非 Windows 或探测失败返回 False。"""
    if os.name != "nt":
        return False
    try:
        out = subprocess.run(["tasklist", "/FI", "IMAGENAME eq Obsidian.exe"],
                             capture_output=True, timeout=20)
        return b"Obsidian.exe" in out.stdout
    except Exception:
        return False


def _looks_like_path(s):
    """是否像 vault 内相对路径（用于判定「该值是否应存在于磁盘」）。"""
    if not isinstance(s, str) or not s:
        return False
    if s.startswith(("http://", "https://", "obsidian://", "app://")):
        return False
    if ":" in s[:3] and os.name == "nt":      # 盘符
        return False
    return s.endswith((".md", ".pdf", ".png", ".jpg", ".jpeg", ".gif",
                       ".webp", ".svg", ".base", ".json", ".txt", ".csv"))


def find_dead(obj, path="", out=None):
    """递归找出所有指向不存在文件的路径字符串。返回 [(json路径, 值)]。"""
    if out is None:
        out = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_dead(v, "%s/%s" % (path, k), out)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_dead(v, "%s[%d]" % (path, i), out)
    elif isinstance(obj, str):
        if _looks_like_path(obj) and not os.path.exists(obj):
            out.append((path, obj))
    return out


def purge(obj):
    """就地删除死引用；返回删除条数。list 元素被过滤，dict 值置空字符串。

    对 dict 值不整体删键，避免破坏 Obsidian 的 schema（键在、值为空更安全）。
    """
    n = 0
    if isinstance(obj, dict):
        for k in list(obj.keys()):
            v = obj[k]
            if isinstance(v, str) and _looks_like_path(v) and not os.path.exists(v):
                obj[k] = ""
                n += 1
            else:
                n += purge(v)
    elif isinstance(obj, list):
        keep = []
        for v in obj:
            if isinstance(v, str) and _looks_like_path(v) and not os.path.exists(v):
                n += 1
                continue
            n += purge(v)
            keep.append(v)
        obj[:] = keep
    return n


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。"""
    ok = True
    # 正例：真实存在的工作区文件可解析
    p = WS
    ex = os.path.exists(p)
    print(f"  [{'ok' if ex else 'info'}] {p} 存在 -> {ex}")
    if ex:
        try:
            d = json.loads(open(p, "rb").read().decode("utf-8"))
            print(f"  [ok] workspace.json 可解析为 JSON")
        except Exception as e:
            print(f"  [FAIL] workspace.json 解析失败: {e}")
            ok = False
    # 夹具：_looks_like_path 正例/反例
    cases = [("wiki/index.md", True, "vault 相对 md 路径"),
             ("raw/pdf/x.pdf", True, "pdf 路径"),
             ("https://example.com/a.md", False, "URL 不算路径"),
             ("obsidian://open?vault=x", False, "obsidian URI"),
             ("", False, "空串"),
             ("just some text", False, "普通文本")]
    for s, want, label in cases:
        got = _looks_like_path(s)
        print(f"  [{'ok' if got == want else 'FAIL'}] 夹具 {label}: {got}")
        ok = ok and got == want
    # 夹具：find_dead/purge 在合成对象上的行为（含反例：存在的文件不得被删）
    tmp = "wiki/index.md"      # 必然存在
    missing = "绝不存在的目录/xyz.md"
    obj = {"a": {"file": missing}, "b": [missing, tmp, "text"], "c": tmp}
    dead = find_dead(obj)
    got = len(dead) == 2 and all(v == missing for _, v in dead)
    print(f"  [{'ok' if got else 'FAIL'}] find_dead 只报不存在者 -> {len(dead)} 条")
    ok = ok and got
    n = purge(obj)
    good = (n == 2 and obj["a"]["file"] == "" and obj["b"] == [tmp, "text"]
            and obj["c"] == tmp)
    print(f"  [{'ok' if good else 'FAIL'}] purge 删除 2 条、保留存在的项 -> {n}")
    ok = ok and good
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="清理 workspace.json 死引用")
    ap.add_argument("--apply", action="store_true", help="写盘（默认干跑）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    if not os.path.exists(WS):
        print(f"{WS} 不存在，无需处理")
        return 0

    raw = open(WS, "rb").read().decode("utf-8")
    d = json.loads(raw)
    dead = find_dead(d)
    print(f"发现死引用 {len(dead)} 处:")
    for path, val in dead:
        print(f"   {path}  ->  {val[:100]}")

    if not dead:
        print("无需修改")
        return 0

    if not a.apply:
        print("\n干跑结束。加 --apply 写盘（会先备份到库根 .qc/）")
        return 0

    if obsidian_running():
        print("\n[拒绝写盘] Obsidian 正在运行——它退出时会用内存状态覆盖本文件。")
        print("请先完全退出 Obsidian，再重跑 --apply。")
        return 1

    n = purge(d)
    stamp = datetime.date.today().strftime("%Y%m%d")
    bak = os.path.join(qc_work_dir(create=True), f"workspace_backup_{stamp}.json")
    shutil.copyfile(WS, bak)
    with open(WS, "w", encoding="utf-8", newline="") as fh:
        json.dump(d, fh, ensure_ascii=False, indent=2)
    # 写后复算：必须仍是合法 JSON，且死引用归零
    after = json.loads(open(WS, "rb").read().decode("utf-8"))
    left = len(find_dead(after))
    print(f"\n已清理 {n} 处；备份 -> {bak}")
    print(f"写后复算：剩余死引用 {left}（应为 0）")
    return 0 if left == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
